// requirement: REQ-1.1
import { expect } from '@playwright/test';
import { test } from './fixtures/test';
import { entry, link, button, field, region, search } from './helpers';
test("REQ-1.1: Browse public homepage", async ({ page }) => {
    await entry(page);
    await expect(page.getByRole('img', { name: '12306 logo', exact: true })).toBeVisible();
    for (const name of ['Login', 'Register', 'My 12306'])
        await expect(link(page, name)).toBeVisible();
    for (const name of ['Home', 'Booking', 'Travel guide'])
        await expect(link(page.getByRole('navigation'), name)).toBeVisible();
    const banners = region(page, 'Home banners');
    await expect(banners.getByRole('img', { name: 'Banner 1', exact: true })).toBeVisible();
    await button(banners, 'Next banner').click();
    await expect(banners.getByRole('img', { name: 'Banner 2', exact: true })).toBeVisible();
    await button(banners, 'Next banner').click();
    await expect(banners.getByRole('img', { name: 'Banner 3', exact: true })).toBeVisible();
    const s = region(page, 'Ticket search');
    await expect(s.getByPlaceholder('From', { exact: true })).toHaveCount(1);
    await expect(s.getByPlaceholder('To', { exact: true })).toHaveCount(1);
    await expect(field(s, 'Date')).toHaveCount(1);
    await expect(button(s, 'Search')).toBeEnabled();
    await expect(region(page, 'Quick Guide')).toBeVisible();
    for (const name of ['How to book tickets online?', 'More'])
        await expect(link(region(page, 'Quick Guide'), name)).toBeVisible();
});

// requirement: REQ-2.1.1
import { expect } from '@playwright/test';
import { test } from './fixtures/test';
import { entry, link, button, field, region, row, home, login, center, orders, orderSetup, search, booking, confirmation } from './helpers';

test("REQ-2.1.1: Open traveler registration", async ({ page }) => {
  await entry(page);
  await link(page, 'Register').click();
  for (const name of ['Nationality', 'Name', 'Passport number', 'Password', 'Confirm Password']) await expect(field(page, name)).toBeVisible();
  await expect(button(page, 'Register')).toBeVisible();
});

// requirement: REQ-2.1.2
import { expect } from '@playwright/test';
import { test } from './fixtures/test';
import { entry, link, text, register, login, home } from './helpers';
test("REQ-2.1.2: Create durable account", async ({ page }) => {
    await entry(page);
    await register(page);
    await text(page, 'Registration successful.');
    await home(page);
    if (await link(page, 'Sign Out').isVisible())
        await link(page, 'Sign Out').click();
    await page.reload();
    await login(page, 'traveler_new');
    await page.reload();
    await expect(link(page, 'Sign Out')).toBeVisible();
});

// requirement: REQ-2.1.3
import { expect } from '@playwright/test';
import { test } from './fixtures/test';
import { entry, link, button, field, text, register, home, confirmation } from './helpers';
test("REQ-2.1.3: Reject missing fields", async ({ page }) => {
    await entry(page);
    await link(page, 'Register').click();
    await button(page, 'Register').click();
    await text(page, 'Please fill in all required fields.');
    await expect(field(page, 'Username')).toBeVisible();
    await expect(page.getByText('Registration successful.', { exact: true })).not.toBeVisible();
});
test("REQ-2.1.3: Reject duplicate passport", async ({ page }) => {
    await entry(page);
    await register(page, { passport: 'P20260002', username: 'existing_passport' });
    await home(page);
    if (await link(page, 'Sign Out').isVisible())
        await link(page, 'Sign Out').click();
    await register(page, { "passport": "P20260002", "username": "duplicate_passport_user" });
    await text(page, "Passport number already exists.");
    await expect(field(page, 'Username')).toBeVisible();
    await expect(page.getByText('Registration successful.', { exact: true })).not.toBeVisible();
});
test("REQ-2.1.3: Reject duplicate username", async ({ page }) => {
    await entry(page);
    await register(page, { passport: 'P20260104', username: 'username_taken' });
    await home(page);
    if (await link(page, 'Sign Out').isVisible())
        await link(page, 'Sign Out').click();
    await register(page, { "passport": "P20260004", "username": "username_taken" });
    await text(page, "Username already exists.");
    await expect(field(page, 'Username')).toBeVisible();
    await expect(page.getByText('Registration successful.', { exact: true })).not.toBeVisible();
});
test("REQ-2.1.3: Reject password mismatch", async ({ page }) => {
    await entry(page);
    await register(page, { "passport": "P20260007", "username": "traveler_mismatch", "confirm": "Password123!Mismatch" });
    await text(page, "Passwords do not match.");
    await expect(field(page, 'Username')).toBeVisible();
    await expect(page.getByText('Registration successful.', { exact: true })).not.toBeVisible();
});
test("REQ-2.1.3: Reject invalid email", async ({ page }) => {
    await entry(page);
    await register(page, { "passport": "P20260008", "username": "traveler_invalid_email", "email": "invalid-email" });
    await text(page, "Invalid email address format.");
    await expect(field(page, 'Username')).toBeVisible();
    await expect(page.getByText('Registration successful.', { exact: true })).not.toBeVisible();
});
test("REQ-2.1.3: Require agreement acceptance", async ({ page }) => {
    await entry(page);
    await register(page, { "passport": "P20260009", "username": "traveler_agreement", "agree": false });
    await text(page, "Please agree to the Terms of Service and Privacy Policy.");
    await expect(field(page, 'Username')).toBeVisible();
    await expect(page.getByText('Registration successful.', { exact: true })).not.toBeVisible();
});
test("REQ-2.1.3: Reject missing confirmation password", async ({ page }) => {
    await entry(page);
    await register(page, { username: 'traveler_missing_confirm', passport: 'P20260015', confirm: '' });
    await text(page, 'Please fill in all required fields.');
    await expect(field(page, 'Confirm Password')).toBeVisible();
    await expect(page.getByText('Registration successful.', { exact: true })).not.toBeVisible();
